// Nin Nin CPC - load constants. Hand-written. Included by config.h; the build
// script passes -DNN_LOAD=1, 2 or 3. The per level tables of all ten levels are
// in nn_levels.h (generated by tools/nn_assets.py); a load plays NN_FIRST ..
// NN_FIRST + NN_LEVELS - 1 of them. comp_cpc.sh / .bat have the same numbers
// for each load (levels, SCREENS, MAPMAX, LOCKS): keep them together.
//
//   load 1: THE BOSQUE, THE DESERT, GOOD MARSH, DE NADAL 1
//   load 2: CUEVA CAVE, NOSHE WOOD, DE NADAL 2
//   load 3: MARSHY GOO, ICY DUSTER, EL CASTLER

#ifndef NN_LOAD
	#define NN_LOAD 		1
#endif

#if NN_LOAD == 1
	#define NN_FIRST 		0
	#define NN_LEVELS 		4
	#define NN_MAP_MAX 		680		// largest RLE44 map of the load (627)
#elif NN_LOAD == 2
	#define NN_FIRST 		4
	#define NN_LEVELS 		3
	#define NN_MAP_MAX 		600		// (591)
#else
	#define NN_FIRST 		7
	#define NN_LEVELS 		3
	#define NN_MAP_MAX 		830		// (824)
	#define NN_CASTLE 				// EL CASTLER's puzzles (nn_castle.h)
#endif

// The largest map of every load has 24 screens: the level area is sized for
// it (MAP_W x MAP_H only sizes the arrays: VARIABLE_MAP_W).
#define NN_MAP_W 			12
#define NN_MAP_H 			2

// The level area (enems.h), every level blob (cpc/lvlN_area.zx0) is
// decompressed over it, from _level_area:
//   cerrojos  MAX_LOCKS x 4	rle44map_sp mk1locks maxlocks=MAX_LOCKS
//   malotes   S x 27			ene2h bin screens=S (3 enemies x 9 bytes)
//   hotspots  S x 3			  + (xy, type, act)
//   mapa      up to NN_MAP_MAX	rle44map_sp: index (2 x S) + screens, last
// with S = NN_MAP_W x NN_MAP_H. comp_cpc.sh checks the map sizes.
#define MAX_LOCKS 			4

// Each level's sprite cells (gfx/cpc/spritesN.png, 16 cells of 64 bytes:
// enemies 0-7, swim frames 8-13, drop 14) are decompressed to NN_SPR_BASE,
// free RAM above the CPC_DIRTY buffers (CD_FREE).
#define NN_SPR_BASE 		0xB980
#define NN_SPR_CELLS 		16

// Broken blocks and coins taken, one bit per tile: 19 bytes x screens, above
// the sprite cells
#define NN_CLEAR 			0xBD80
